package pe.cruzroja.convocatorias.inventory.domain; import java.util.UUID; public class Material {private final UUID id; private final String name,category; private int total,reserved; public Material(UUID id,String name,String category,int total,int reserved){if(id==null||name==null||name.isBlank()||total<0||reserved<0||reserved>total)throw new IllegalArgumentException("Material inválido");this.id=id;this.name=name;this.category=category;this.total=total;this.reserved=reserved;} public int available(){return total-reserved;} public void reserve(int quantity){if(quantity<=0||quantity>available())throw new IllegalArgumentException("Stock insuficiente");reserved+=quantity;} public void release(int quantity){if(quantity<=0||quantity>reserved)throw new IllegalArgumentException("Cantidad inválida");reserved-=quantity;} public void lose(int quantity){release(quantity);total-=quantity;} public UUID id(){return id;} public String name(){return name;} public String category(){return category;} public int total(){return total;} public int reserved(){return reserved;} }
